{"command":"create","path":"/workspace/codebase/rust/src/main.rs","file_text":"use std::env;
use std::path::{Path, PathBuf};
use std::process::{Command, ExitCode};

fn bridge_path() -> PathBuf {
    if let Some(path) = env::var_os("JSCODESHIFT_BRIDGE") {
        return PathBuf::from(path);
    }

    Path::new(env!("CARGO_MANIFEST_DIR"))
        .parent()
        .expect("Rust crate must be inside the package root")
        .join("bridge/transform-host.js")
}

fn node_command() -> String {
    env::var("JSCODESHIFT_NODE").unwrap_or_else(|_| "node".to_owned())
}

fn main() -> ExitCode {
    let bridge = bridge_path();
    if !bridge.is_file() {
        eprintln!("jscodeshift: JavaScript transform bridge is missing: {}", bridge.display());
        return ExitCode::from(1);
    }

    let status = Command::new(node_command())
        .arg(bridge)
        .args(env::args_os().skip(1))
        .status();

    match status {
        Ok(status) => ExitCode::from(status.code().unwrap_or(1) as u8),
        Err(error) => {
            eprintln!("jscodeshift: could not start JavaScript transform host: {error}");
            ExitCode::from(1)
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn default_bridge_is_packaged_with_the_crate() {
        assert!(bridge_path().ends_with("bridge/transform-host.js"));
    }

    #[test]
    fn node_command_defaults_to_node() {
        assert!(!node_command().is_empty());
    }
}
